insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000003e', 'en', null, 'Zoology', 'Zoology is the scientific study of animals - their bodies, behavior, classification, and evolution - from microscopic invertebrates to the largest whales. This foundations course surveys the animal kingdom, moving from taxonomy and the major phyla through physiology, reproduction, behavior, ecology, evolution, and conservation. Structure and topics adapted from the Zoology overview on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 60, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000003e', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Zoology is best described as the scientific study of...","options":["plants","animals","rocks and minerals","weather"],"answer":1,"explanation":"Zoology is the branch of biology that studies animals - their form, function, behavior, and evolution."},{"prompt":"The two-word Latin naming system for species (for example, Homo sapiens) is called...","options":["binomial nomenclature","the metric system","common naming","the food web"],"answer":0,"explanation":"Binomial nomenclature gives each species a genus name and a species name - see ''Classification and taxonomy of animals''."},{"prompt":"Which of these animals is an invertebrate?","options":["frog","octopus","sparrow","shark"],"answer":1,"explanation":"An octopus is a mollusc and has no backbone; frogs, sparrows, and sharks are vertebrates."},{"prompt":"Insects, spiders, and crabs all belong to which phylum?","options":["Mollusca","Chordata","Arthropoda","Cnidaria"],"answer":2,"explanation":"Arthropods have jointed legs and a hard exoskeleton; it is the largest animal phylum."},{"prompt":"Animals that have a backbone are called...","options":["invertebrates","vertebrates","arthropods","sponges"],"answer":1,"explanation":"Vertebrates include fish, amphibians, reptiles, birds, and mammals."},{"prompt":"The scientific study of animal behavior is called...","options":["ecology","ethology","anatomy","taxonomy"],"answer":1,"explanation":"Ethology studies how and why animals behave as they do - see ''Behavior, ecology, evolution, and conservation''."},{"prompt":"Evolution by natural selection was famously explained in the 1800s by...","options":["Carl Linnaeus","Aristotle","Charles Darwin","Gregor Mendel"],"answer":2,"explanation":"Charles Darwin, along with Alfred Russel Wallace, described natural selection."},{"prompt":"A species facing a very high risk of extinction in the wild is described as...","options":["abundant","endangered","domesticated","nocturnal"],"answer":1,"explanation":"Endangered species are at serious risk of extinction and are a focus of conservation."}]}'::jsonb, null, 10),
  (2, 'What zoology is and the history of the field', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Say what zoology studies, place a few milestones of the field in order, and explain how animal science grew from careful observation into a modern experimental discipline. Warm-up: before you read on, try to name one scientist from the diagnostic who shaped how we classify or explain living things, and say in a sentence what they are known for."},{"heading":"The idea","text":"Zoology is the branch of biology devoted to animals - their structure, function, growth, development, classification, behavior, and evolution. The word joins the Greek roots zoion, meaning animal, and logos, meaning study. People have observed animals since prehistoric times, but zoology became systematic with the ancient Greeks. Aristotle grouped hundreds of species by shared features and dissected many, so he is often called the first zoologist. For centuries the field was mainly natural history: describing, collecting, and cataloging living things. The microscope, invented in the 1600s, revealed cells and tiny organisms no one had seen before. In the 1700s Carl Linnaeus built the naming and ranking system still used today. In the 1800s Charles Darwin and Alfred Russel Wallace supplied the unifying idea of evolution by natural selection, which turned a static catalog of forms into a connected tree of shared ancestry. Modern zoology blends fieldwork, laboratory experiment, genetics, and computer modeling."},{"heading":"Key groups & examples","text":"Zoology branches into many specialties. Taxonomy names and classifies species. Anatomy and physiology study form and function. Ethology studies behavior, while ecology studies how animals interact with one another and their surroundings. Other branches focus on a single group: entomology (insects), ichthyology (fish), herpetology (amphibians and reptiles), ornithology (birds), and mammalogy (mammals). The history of the field is marked by a handful of pivotal figures. Aristotle first organized animal knowledge around 350 BCE. Carl Linnaeus, in the 1700s, gave every species a two-part name and nested ranks. Jean-Baptiste Lamarck proposed an early, flawed theory of change over time and helped popularize the term biology. Charles Darwin, after his voyage on the Beagle, explained how natural selection drives adaptation. Gregor Mendel, working with pea plants, uncovered the rules of heredity that would later join with Darwin''s ideas to form modern evolutionary biology. Each contributor handed the next generation a sharper tool."},{"heading":"Your turn","text":"1) What does the word zoology literally refer to? 2) Who is often called the first zoologist? 3) Which scientist created the two-word naming system still used today? 4) Name the branch of zoology that studies insects. 5) Which idea connected the catalog of species into a family tree? Answers: 1) The study of animals. 2) Aristotle. 3) Carl Linnaeus. 4) Entomology. 5) Evolution by natural selection."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating zoology as only the study of large or familiar animals; it covers every animal, from microscopic rotifers to blue whales. Mistake: thinking classification and evolution are unrelated, when modern classification tries to reflect evolutionary history. Exit: (a) Name two branches of zoology. (b) Which two naturalists are credited with natural selection? Answers: any two of taxonomy, physiology, ethology, ecology, entomology, ornithology, and so on; Charles Darwin and Alfred Russel Wallace."}]}'::jsonb, 'Scientific names use two parts: a capitalized genus and a lowercase species, both written in italics, as in Homo sapiens.', 12),
  (3, 'Classification and taxonomy of animals', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"List the ranks of biological classification in order, explain how binomial nomenclature names a species, and recognize several of the major animal phyla by a defining feature. Warm-up: from the diagnostic, can you recall the two-word Latin name for modern humans and say which part of it is the genus?"},{"heading":"The idea","text":"Taxonomy is the science of naming, describing, and classifying organisms; systematics adds the study of how they are related. Carl Linnaeus set up a nested hierarchy of ranks that biologists still use: domain, kingdom, phylum, class, order, family, genus, and species. Each species receives a two-part Latin name, its genus capitalized and its species lowercase, both italicized, as in Panthera leo for the lion. All animals sit in the kingdom Animalia, whose members are multicellular, eukaryotic, and heterotrophic, meaning they get energy by eating other organisms rather than making their own food; they lack cell walls, and most can move during at least one stage of life. Modern classification aims to reflect evolutionary history, so a good group ideally contains an ancestor and all of its descendants. The method that builds these trees from shared, newly evolved traits is called cladistics, and the branching diagrams it produces are called cladograms."},{"heading":"Key groups & examples","text":"The animal kingdom is divided into roughly thirty phyla, but a handful contain most familiar animals. Porifera are the sponges, simple filter feeders with no true tissues. Cnidaria include jellyfish, corals, and sea anemones, all armed with stinging cells. Platyhelminthes are the flatworms, and Nematoda are the roundworms. Annelida are segmented worms such as the earthworm. Mollusca is a huge phylum of snails, clams, squid, and octopuses. Arthropoda, the largest phylum of all, holds insects, crustaceans, arachnids, and millipedes, united by jointed legs and a hard exoskeleton. Echinodermata are spiny-skinned marine animals such as sea stars and urchins. Finally, Chordata includes all the vertebrates plus a few invertebrate relatives, defined by a nerve cord running along the back. Together, arthropods and chordates account for the vast majority of named animal species, with insects alone making up more than half of all described animals."},{"heading":"Your turn","text":"1) List the eight main ranks from broadest to narrowest. 2) In Panthera leo, which word is the genus? 3) Name three features shared by all members of kingdom Animalia. 4) Which phylum contains insects and crabs? 5) What is a cladogram? Answers: 1) Domain, kingdom, phylum, class, order, family, genus, species. 2) Panthera. 3) Any three of: multicellular, eukaryotic, heterotrophic, lacking cell walls, able to move. 4) Arthropoda. 5) A branching diagram showing how groups are related by shared, newly evolved traits."},{"heading":"Common mistakes & exit ticket","text":"Mistake: capitalizing the species part of a Latin name; only the genus is capitalized. Mistake: assuming every animal can move throughout life, when some, such as adult sponges and corals, stay fixed in place. Exit: (a) Which rank is broader, phylum or class? (b) What does heterotrophic mean? Answers: phylum is broader than class; heterotrophic means getting energy by eating other organisms rather than producing food internally."}]}'::jsonb, 'The main ranks, from broadest to narrowest, are domain, kingdom, phylum, class, order, family, genus, and species.', 13),
  (4, 'Invertebrates I: sponges, cnidarians, worms, and molluscs', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the body plans of sponges, cnidarians, the main worm groups, and molluscs, and give a living example of each. Warm-up: roughly what fraction of all animal species do you think lack a backbone? Make a guess before you read the note above, then check it."},{"heading":"The idea","text":"Invertebrates are animals without a backbone, and they make up the overwhelming majority of animal life. The simplest are the sponges (phylum Porifera): they have no true tissues or organs, and instead pump water through pores to filter out food particles. Cnidarians (phylum Cnidaria), such as jellyfish, corals, sea anemones, and hydra, show radial symmetry and carry stinging cells called cnidocytes to capture prey; they have two body layers and a single gut opening that serves as both mouth and anus. Next come the worms, which are not one group but several separate phyla. Flatworms (Platyhelminthes) are thin and soft, including free-living planarians and parasitic tapeworms. Roundworms (Nematoda) are slender and astonishingly abundant in soil and water. Segmented worms (Annelida), such as earthworms and leeches, have bodies built from repeated rings. Molluscs (Mollusca) are soft-bodied animals, often with a shell, that include snails, clams, and the remarkably clever octopuses and squid."},{"heading":"Key groups & examples","text":"Sponges include the bath sponge and the giant barrel sponge, which can live for centuries. Cnidarians include the moon jelly, reef-building stony corals, and the Portuguese man o'' war, which is actually a colony of cooperating individuals. Flatworms include the planarian, famous for regenerating lost parts, and the beef tapeworm, a gut parasite. Roundworms include the tiny Caenorhabditis elegans, a favorite laboratory animal, and parasitic hookworms. Segmented worms include the common earthworm, which aerates soil, and the medicinal leech. Molluscs split into major classes: gastropods (snails and slugs), bivalves (clams, oysters, and mussels), and cephalopods (octopuses, squid, nautiluses, and cuttlefish). Cephalopods have the most complex nervous systems of any invertebrate; an octopus can open jars, solve mazes, and change color in an instant. Despite their soft bodies, molluscs rank second only to arthropods in the number of described species."},{"heading":"Your turn","text":"1) Which invertebrate group has no true tissues? 2) What are the stinging cells of cnidarians called? 3) Name the three worm phyla covered here. 4) To which phylum do octopuses belong, and which class within it? 5) Give one reason earthworms benefit soil. Answers: 1) Sponges (Porifera). 2) Cnidocytes. 3) Platyhelminthes (flatworms), Nematoda (roundworms), and Annelida (segmented worms). 4) Mollusca, class Cephalopoda. 5) They burrow through and aerate the soil, mixing and enriching it."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking all worms are closely related; flatworms, roundworms, and segmented worms sit in separate phyla with different body plans. Mistake: calling a jellyfish a fish, when it is a cnidarian with no bones, brain, or blood. Exit: (a) What body symmetry do cnidarians show? (b) Name the three main classes of molluscs. Answers: radial symmetry; gastropods, bivalves, and cephalopods."}]}'::jsonb, 'Invertebrate is not a formal taxonomic group; it simply means any animal without a backbone, which is more than ninety-five percent of all animal species.', 13),
  (5, 'Invertebrates II: arthropods and echinoderms', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why arthropods are so successful, name the four main arthropod groups with an example of each, and describe the unusual body plan of echinoderms. Warm-up: what do an ant, a lobster, a scorpion, and a butterfly all have in common? Jot down a guess before you read."},{"heading":"The idea","text":"Arthropods (phylum Arthropoda) are the most successful animals on Earth by almost any measure: they make up more than eighty percent of all known animal species. Three features drive their success. First, a hard external skeleton, or exoskeleton, made of chitin, which supports the body and guards against water loss. Second, jointed, segmented legs that allow precise and varied movement. Third, a segmented body often grouped into regions such as head, thorax, and abdomen. Because the exoskeleton cannot stretch, arthropods must molt, shedding the old shell and expanding before the new one hardens. Echinoderms (phylum Echinodermata) are a very different story. These marine animals show five-part radial symmetry as adults, move using a unique water vascular system of fluid-filled tubes and tiny tube feet, and carry an internal skeleton of calcium plates just under the skin. Many can regenerate lost arms, and a few can regrow an entire body from a fragment."},{"heading":"Key groups & examples","text":"The four main arthropod groups are insects, crustaceans, arachnids, and myriapods. Insects, such as beetles, ants, bees, and butterflies, have six legs, three body regions, and usually wings; they are the only invertebrates that truly fly. Crustaceans, such as crabs, lobsters, shrimp, and barnacles, are mostly aquatic and breathe through gills. Arachnids, such as spiders, scorpions, ticks, and mites, have eight legs and two body regions, and never have wings or antennae. Myriapods are the many-legged centipedes and millipedes. Echinoderms include the sea star, which can pry open clams and regrow a lost arm; the sea urchin, a spiny grazer of algae; the sea cucumber, a soft bottom feeder; and the brittle star. Although echinoderm larvae are bilaterally symmetric, the adults reorganize into their famous five-armed radial form, a clue that they are more closely related to the chordates than their looks suggest."},{"heading":"Your turn","text":"1) What is the arthropod exoskeleton made of? 2) Why must arthropods molt? 3) How many legs does an insect have, and how many does an arachnid have? 4) What system do echinoderms use to move? 5) Name two echinoderms. Answers: 1) Chitin. 2) The rigid exoskeleton cannot grow, so the animal sheds it to get larger. 3) Insects have six legs; arachnids have eight. 4) A water vascular system with tube feet. 5) Any two of: sea star, sea urchin, sea cucumber, brittle star."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling a spider an insect; spiders are arachnids with eight legs and two body regions, not six legs and three. Mistake: assuming echinoderms are simple because they look like plants or flowers, when they have a complex water vascular system and are close relatives of the chordates. Exit: (a) Which arthropod group can fly? (b) What kind of symmetry do adult echinoderms show? Answers: insects; five-part radial symmetry."}]}'::jsonb, 'Arthropod means jointed foot, from Greek; the name points to the hinged, segmented legs shared across the whole phylum.', 13),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Who is often called the first zoologist for grouping and dissecting hundreds of species in ancient Greece?","options":["Charles Darwin","Carl Linnaeus","Aristotle","Gregor Mendel"],"answer":2,"explanation":"Aristotle systematically classified and dissected animals long before modern biology."},{"prompt":"Listed from broadest to narrowest, which run of ranks is correct?","options":["species, genus, family, order","kingdom, phylum, class, order","order, class, phylum, kingdom","genus, species, family, class"],"answer":1,"explanation":"The ranks run domain, kingdom, phylum, class, order, family, genus, species."},{"prompt":"Sponges (phylum Porifera) are unusual among animals because they...","options":["have a backbone","have no true tissues or organs","can fly","have eight legs"],"answer":1,"explanation":"Sponges lack true tissues and filter food from water drawn through their pores."},{"prompt":"The stinging cells that cnidarians use to capture prey are called...","options":["tube feet","cnidocytes","chitin plates","gills"],"answer":1,"explanation":"Cnidocytes are the stinging cells found in jellyfish, corals, and sea anemones."},{"prompt":"Which phylum makes up more than eighty percent of all known animal species?","options":["Mollusca","Chordata","Arthropoda","Echinodermata"],"answer":2,"explanation":"Arthropods - insects, crustaceans, arachnids, and myriapods - dominate animal diversity."},{"prompt":"Adult echinoderms, such as sea stars, are known for which kind of symmetry?","options":["bilateral","five-part radial","no symmetry","spiral"],"answer":1,"explanation":"Adult echinoderms show five-part radial symmetry, though their larvae are bilateral."}]}'::jsonb, null, 8),
  (7, 'Vertebrates and the chordate body plan', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"List the four hallmark features of chordates, name the five main vertebrate groups in the order they appeared, and give a defining trait of each. Warm-up: what single feature do a trout, a frog, a lizard, an eagle, and a dog all share that a crab does not?"},{"heading":"The idea","text":"Chordates (phylum Chordata) are defined by four features that appear at some point in the life cycle: a stiff dorsal rod called a notochord, a hollow nerve cord running along the back, pharyngeal slits in the throat region, and a muscular tail that extends past the anus. In vertebrates the notochord is replaced during development by a backbone of bone or cartilage that protects the spinal cord. A vertebrate body plan also typically features a distinct head with a skull and a complex brain, an internal skeleton that grows with the animal, and a closed circulatory system driven by a chambered heart. This internal skeleton is a key advantage over the arthropod exoskeleton: it supports large bodies and grows continuously, with no need to molt. These shared features link the familiar backboned animals into one branch of the tree of life, from the smallest minnow to the blue whale."},{"heading":"Key groups & examples","text":"The vertebrates fall into five main groups, roughly in the order they evolved. Fish came first: cartilaginous fish such as sharks and rays, and bony fish such as the trout and the clownfish; they breathe with gills and are cold-blooded. Amphibians, such as frogs, toads, and salamanders, were the first vertebrates to live on land, but they still need water or moist skin and lay jelly-coated eggs. Reptiles, such as lizards, snakes, turtles, and crocodiles, evolved scaly skin and the amniotic egg, which freed them from water. Birds, descended from dinosaurs, are warm-blooded, feathered, and built for flight, with hollow bones and a four-chambered heart. Mammals, such as mice, bats, whales, and humans, are warm-blooded, have hair, and nurse their young with milk from mammary glands. Birds and mammals independently evolved a warm-blooded metabolism, which lets them stay active even in cold conditions."},{"heading":"Your turn","text":"1) Name the four defining features of chordates. 2) What replaces the notochord in adult vertebrates? 3) Which vertebrate group was the first to live on land? 4) Which two groups are warm-blooded? 5) What key innovation let reptiles breed away from water? Answers: 1) A notochord, a dorsal hollow nerve cord, pharyngeal slits, and a post-anal tail. 2) A backbone of bone or cartilage. 3) Amphibians. 4) Birds and mammals. 5) The amniotic egg, which carries its own water supply inside a protective shell."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking sharks are not fish; sharks are cartilaginous fish, with skeletons of cartilage rather than bone. Mistake: assuming all vertebrates are warm-blooded, when only birds and mammals are. Exit: (a) Which internal structure defines a vertebrate within the chordates? (b) What feature do mammals use to feed their young? Answers: a backbone, or vertebral column, protecting the spinal cord; mammary glands that produce milk."}]}'::jsonb, 'All vertebrates are chordates, but not all chordates are vertebrates; a few chordate relatives never develop a bony backbone.', 13),
  (8, 'Animal physiology, reproduction, and development', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the major organ systems and what each does, contrast sexual and asexual reproduction, and outline how an embryo develops into an adult. Warm-up: before reading, try to list three organ systems in your own body and say in a few words what each one is for."},{"heading":"The idea","text":"Physiology is the study of how animal bodies function. Larger animals rely on specialized organ systems that work together. The digestive system breaks food into usable nutrients; the respiratory system exchanges oxygen and carbon dioxide through lungs, gills, or skin; the circulatory system carries blood, nutrients, and waste around the body. The nervous system senses and responds to the world, while the endocrine system coordinates the body more slowly using hormones. The muscular and skeletal systems produce movement, the excretory system removes waste, and the immune system defends against disease. Reproduction continues the species. In asexual reproduction a single parent produces offspring that are genetic copies of itself, as when a hydra buds or a sea star regrows a whole body from an arm. In sexual reproduction two parents each contribute half the genetic material through sex cells, producing varied offspring. That variation is the raw material on which natural selection later acts."},{"heading":"Key groups & examples","text":"Reproductive and developmental strategies vary widely. Fertilization may be external, as when fish and frogs release eggs and sperm into water, or internal, as in reptiles, birds, and mammals. Animals are often grouped by how their embryos are nourished: oviparous animals lay eggs that develop outside the body (birds, most reptiles, and insects); viviparous animals give birth to live young nourished inside the mother (most mammals); and ovoviviparous animals keep eggs inside the body until they hatch (some sharks and snakes). After fertilization, a single cell divides repeatedly, forms a hollow ball of cells, then folds inward to create the layers that become tissues and organs. Some animals develop directly into a small version of the adult, while others pass through larval stages and metamorphosis - a caterpillar reorganizing into a butterfly, or a tadpole into a frog. Parental care ranges from none at all to years of feeding and protection."},{"heading":"Your turn","text":"1) Which organ system exchanges oxygen and carbon dioxide? 2) Name one advantage of sexual reproduction over asexual reproduction. 3) What does oviparous mean? 4) Give an example of metamorphosis. 5) Which system uses hormones to coordinate the body? Answers: 1) The respiratory system. 2) It produces genetic variation, the raw material for adaptation. 3) Laying eggs that develop and hatch outside the mother''s body. 4) A tadpole becoming a frog, or a caterpillar becoming a butterfly. 5) The endocrine system."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing the circulatory and respiratory systems; one moves blood, the other exchanges gases, though they work closely together. Mistake: assuming live birth is unique to mammals, when some sharks and snakes also bear live young. Exit: (a) How do asexual and sexual reproduction differ in terms of parents and genes? (b) Name the three nourishment categories based on eggs and live birth. Answers: asexual needs one parent and copies its genes, while sexual needs two parents and mixes genes; oviparous, viviparous, and ovoviviparous."}]}'::jsonb, 'Physiology asks how a body works; anatomy asks how it is built. The two go hand in hand but answer different questions.', 14),
  (9, 'Key terms', 'vocab', '{"items":[{"term":"taxonomy","translation":"the science of naming, describing, and classifying living things","example":"Taxonomy places the lion in the genus Panthera and the species leo."},{"term":"phylum","translation":"a major rank of classification just below kingdom, grouping animals that share a body plan","example":"Insects and crabs both sit in the phylum Arthropoda."},{"term":"invertebrate","translation":"any animal that lacks a backbone","example":"Worms, snails, and insects are all invertebrates."},{"term":"vertebrate","translation":"an animal with a backbone, such as a fish, bird, or mammal","example":"A frog is a vertebrate; a jellyfish is not."},{"term":"exoskeleton","translation":"a hard external skeleton that supports and protects the body","example":"A beetle must molt because its exoskeleton cannot grow."},{"term":"metamorphosis","translation":"a major change in body form during an animal''s development","example":"Through metamorphosis a caterpillar becomes a butterfly."},{"term":"ethology","translation":"the scientific study of animal behavior, especially in natural settings","example":"Ethology helps explain why geese fly in a V formation."},{"term":"natural selection","translation":"the process by which heritable traits that aid survival and reproduction become more common over generations","example":"Natural selection favored longer necks in the ancestors of giraffes."}]}'::jsonb, null, 10),
  (10, 'Behavior, ecology, evolution, and conservation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish learned from instinctive behavior, define key ecology terms, explain adaptation by natural selection, and describe why biodiversity matters and how it is protected. Warm-up: is a spider spinning its very first web acting on instinct or on learning? Predict before you read."},{"heading":"The idea","text":"Ethology is the study of animal behavior. Some behavior is innate, present without any learning, such as a spider spinning a web or a newly hatched sea turtle heading toward the sea. Other behavior is learned through experience, such as a crow shaping a tool or a wolf pup learning to hunt with its pack. Many behaviors blend both. Ecology studies how animals interact with one another and with their environment. A population is all the members of one species in an area; a community is the different species living together there; and an ecosystem adds the nonliving surroundings such as water, soil, and climate. Within a community, each species has a niche, its role and way of making a living. Energy flows from producers to plant eaters to predators along food chains, which interlock into food webs. Important relationships include predation, competition for resources, and symbiosis, in which two species live in close partnership."},{"heading":"Key groups & examples","text":"Over long spans of time, populations change through evolution. Natural selection is the central mechanism: individuals with traits better suited to their surroundings tend to survive and reproduce, so those traits grow more common across generations. The result is adaptation - the camouflage of a stick insect, the streamlined body of a dolphin, the long tongue of an anteater. New species form when populations become isolated and gradually diverge, a process called speciation. All of this variety, from genes to species to whole ecosystems, is called biodiversity, and it underpins clean water, pollination, and stable food supplies. Today many species face pressure from habitat loss, pollution, overhunting, invasive species, and a changing climate, and extinction rates run far above the natural background level. Conservation works to slow this loss through protected reserves, captive breeding programs, laws against wildlife trafficking, and the restoration of damaged habitats. Risk labels such as endangered and vulnerable help set priorities."},{"heading":"Your turn","text":"1) What is the difference between innate and learned behavior? 2) Define an ecosystem. 3) What is an animal''s niche? 4) In one sentence, how does natural selection produce adaptation? 5) Name two threats to biodiversity. Answers: 1) Innate behavior appears without learning, while learned behavior comes from experience. 2) A community of species together with the nonliving parts of their environment. 3) Its role and way of life within a community. 4) Individuals with better-suited heritable traits survive and reproduce more, so those traits spread. 5) Any two of: habitat loss, pollution, overhunting, invasive species, climate change."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking individuals evolve; an individual is born with fixed traits, while a population evolves as trait frequencies shift across generations. Mistake: treating natural selection as a conscious choice, when it is simply the uneven survival and reproduction of varied individuals. Exit: (a) What is biodiversity? (b) Name one conservation method used to protect endangered species. Answers: the full variety of life, from genes to species to ecosystems; any of protected reserves, captive breeding programs, anti-trafficking laws, or habitat restoration."}]}'::jsonb, 'An adaptation is an inherited trait shaped by natural selection; a habit an animal learns in its lifetime is not passed to its offspring.', 14)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000003e' and l.position = v.pos
);
